INSERT INTO `pages` (`id`, `title`, `description`, `permalink`, `content`, `status`, `created`, `modified`, `show_in_menu`, `date_initial`, `date_final`) VALUES
(1, 'Quem somos', NULL, 'quem-somos', '<p class=\"MsoNormal\" style=\"background-color: white;\"><span style=\"font-size: large; font-family: Verdana, sans-serif;\">Criada em 2015 em Jacare&iacute;/SP, a Maya Cosm&eacute;ticos &eacute; uma empresa de vendas de maquiagem por internet jovem e inovadora, com&nbsp; inten&ccedil;&atilde;o de satisfazer nossos clientes com os melhores produtos, pre&ccedil;os e prazos de entrega.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; background-color: white;\" align=\"center\"><span style=\"font-family: Verdana, sans-serif; font-size: 18px;\">Os nossos valores, s&atilde;o um conjunto de convic&ccedil;&otilde;es partilhadas que est&atilde;o no centro de tudo o que fazemos, e que atendam nossos clientes, assegurando a continuidade da empresa.</span></p>\r\n<p class=\"MsoNormal\" style=\"background-color: white;\"><span style=\"font-size: large;\"><span style=\"font-family: Verdana, sans-serif;\"></span><strong><span style=\"font-family: Verdana, sans-serif; color: #a61922; text-transform: uppercase;\"></span></strong></span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large;\"><strong><span style=\"font-family: Verdana, sans-serif;\"></span></strong></span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large;\"><strong><span style=\"font-family: Verdana, sans-serif;\"> nossos valores:</span></strong></span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt 36pt; text-indent: -18pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large;\"><span style=\"font-family: Symbol;\">&middot;<span style=\"font-stretch: normal; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><strong><span style=\"font-family: Verdana, sans-serif; border: 1pt none windowtext; padding: 0cm;\">Servir bem, para servir sempre</span></strong><span style=\"font-family: Verdana, sans-serif;\"></span></span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large;\"><span style=\"font-family: Verdana, sans-serif; border: 1pt none windowtext; padding: 0cm;\">Conquista da lealdade dos clientes atrav&eacute;s de sua plena satisfa&ccedil;&atilde;o e da constru&ccedil;&atilde;o de rela&ccedil;&otilde;es fortes e duradouras, estabelecendo de parcerias em real comprometimento e flexibilidade.</span><span style=\"font-family: Verdana, sans-serif;\"></span></span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large;\"><strong><span style=\"font-family: Verdana, sans-serif; border: 1pt none windowtext; padding: 0cm;\">&nbsp;</span></strong><span style=\"font-family: Verdana, sans-serif;\"></span></span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt 36pt; text-indent: -18pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large;\"><!--[if !supportLists]--><span style=\"font-family: Symbol;\">&middot;<span style=\"font-stretch: normal; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><strong><span style=\"font-family: Verdana, sans-serif; border: 1pt none windowtext; padding: 0cm;\">Buscando a excel&ecirc;ncia empresarial no ecommerce</span></strong><span style=\"font-family: Verdana, sans-serif;\"></span></span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large; font-family: Verdana, sans-serif;\">Modo de pensar e disponibilizar recursos adequados e implementa&ccedil;&otilde;es na melhoria cont&iacute;nua em nossos processos com simplicidade, agilidade e organiza&ccedil;&atilde;o. Que faz a diferen&ccedil;a de fidelidade aos nossos clientes.</span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large;\"><strong><span style=\"font-family: Verdana, sans-serif; border: 1pt none windowtext; padding: 0cm;\">&nbsp;</span></strong><span style=\"font-family: Verdana, sans-serif;\"></span></span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt 36pt; text-indent: -18pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large;\"><!--[if !supportLists]--><span style=\"font-family: Symbol;\">&middot;<span style=\"font-stretch: normal; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><strong><span style=\"font-family: Verdana, sans-serif; border: 1pt none windowtext; padding: 0cm;\">Ousadia e inova&ccedil;&atilde;o s&atilde;o nossas marcas</span></strong><span style=\"font-family: Verdana, sans-serif;\"></span></span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large; font-family: Verdana, sans-serif;\">Capacidade de inova&ccedil;&atilde;o, de transforma&ccedil;&atilde;o da realidade interna e de influ&ecirc;ncia nos mercados em que atua. Vis&atilde;o estrat&eacute;gica e capacidade de supera&ccedil;&atilde;o de desafios, com criatividade e coragem.</span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large; font-family: Verdana, sans-serif;\"><br /></span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt 36pt; text-indent: -18pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large;\"><span style=\"font-family: Symbol;\">&middot;<strong><span style=\"font-size: large; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\';\">&nbsp; &nbsp; &nbsp; &nbsp; Consultoria de produtos</span></strong></span><span style=\"font-family: Verdana, sans-serif;\"></span></span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large; font-family: Verdana, sans-serif;\">N&atilde;o queremos apenas vender, queremos garantir que nossos clientes esteja comprando os produtos ideais para as suas necessidades, oferecendo conte&uacute;do de qualidade e informativo, atrav&eacute;s das nossas redes sociais e canais de atendimento.&nbsp;</span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large;\"><strong><span style=\"font-family: Verdana, sans-serif; border: 1pt none windowtext; padding: 0cm;\">&nbsp;</span></strong><span style=\"font-family: Verdana, sans-serif;\"></span></span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt 36pt; text-indent: -18pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large;\"><!--[if !supportLists]--><span style=\"font-family: Symbol;\">&middot;<span style=\"font-stretch: normal; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><strong><span style=\"font-family: Verdana, sans-serif; border: 1pt none windowtext; padding: 0cm;\">Constru&iacute;mos um futuro sustent&aacute;vel com perpetuidade</span></strong><span style=\"font-family: Verdana, sans-serif;\"></span></span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large; font-family: Verdana, sans-serif;\">Incessante busca de constru&ccedil;&atilde;o das bases para a perpetuidade da empresa, com rentabilidade aos investidores, respeitando &agrave; qualidade de vida, ao meio ambiente e &agrave; sociedade.&nbsp;</span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large; font-family: Verdana, sans-serif;\"><br /></span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt; line-height: 15pt; background-color: white;\"><span style=\"font-size: large; font-family: Verdana, sans-serif;\">Os valores est&atilde;o presentes na cultura e na rotina de cada empregado formando uma equipe s&oacute;lida e calcada na &eacute;tica e na integridade, a partir da qual a Maya Cosm&eacute;ticos vai continuar oferecendo produtos com qualidade e atendimento diferenciado para seus clientes, e atendo as normas brasileiras e gerando valores para sociedade e demais clientes.</span></p>\r\n<p style=\"margin: 0cm 0cm 0.0001pt;\">&nbsp;</p>\r\n<p class=\"MsoNormal\"><span style=\"font-family: \'Verdana\',sans-serif;\">&nbsp;</span></p>', 'S', '2015-10-13 12:19:29', '2019-11-16 20:26:51', 1, NULL, NULL),
(2, 'Entrega para todo Brasil', NULL, 'entrega-para-todo-brasil', '<p style=\"margin: 0cm 0cm 7.5pt; line-height: 13.5pt; background-color: white;\"><strong><span style=\"font-size: 11pt; font-family: Verdana, sans-serif;\">Entrega para todo Brasil</span></strong><span style=\"font-size: 11pt; font-family: Verdana, sans-serif;\"></span></p>\r\n<p style=\"margin: 0cm 0cm 7.5pt; line-height: 13.5pt; background-color: white;\"><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\">Independente da cidade que voc&ecirc; more, n&oacute;s entregamos os melhores produtos de cosm&eacute;ticos em qualquer lugar do Brasil.</span></p>\r\n<p style=\"margin: 0cm 0cm 7.5pt; line-height: 13.5pt; background-color: white;\"><strong><span style=\"font-size: 11pt; font-family: Verdana, sans-serif;\">Consultar o Frete</span></strong><span style=\"font-size: 11pt; font-family: Verdana, sans-serif;\"></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: 14.25pt; background-color: white;\"><span class=\"a-list-item\"><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\">Acesse a p&aacute;gina do produto que voc&ecirc; quer comprar, insira o CEP para entrega e clique em</span></span><span class=\"apple-converted-space\"><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\"> calcular frete.</span></span><strong><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif; font-weight: normal;\"></span></strong></p>\r\n<p style=\"margin: 0cm 0cm 7.5pt; line-height: 13.5pt; background-color: white;\"><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\">Voc&ecirc; poder&aacute; ter v&aacute;rios endere&ccedil;os de entrega e escolher qual deles deseja utilizar. Para isso basta clicar em trocar endere&ccedil;o de entrega e escolher outro ou cadastrar um novo.</span><span style=\"font-size: 9pt; font-family: Verdana, sans-serif;\"></span></p>\r\n<p style=\"margin: 0cm 0cm 7.5pt; line-height: 13.5pt; background-color: white;\"><strong><span style=\"font-size: 11pt; font-family: Verdana, sans-serif;\">Valor da entrega</span></strong><span style=\"font-size: 11pt; font-family: Verdana, sans-serif;\"></span></p>\r\n<p style=\"margin: 0cm 0cm 7.5pt; line-height: 13.5pt; background-color: white;\"><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\">O c&aacute;lculo do valor da entrega varia de acordo com a sua regi&atilde;o. O valor &eacute; calculado automaticamente pelo nosso sistema e em sua sacola &eacute; confirmado o valor conforme seu endere&ccedil;o.</span></p>\r\n<p style=\"margin: 0cm 0cm 7.5pt; line-height: 13.5pt; background-color: white;\"><strong><span style=\"font-size: 11pt; font-family: Verdana, sans-serif;\">Prazo de Entrega</span></strong><span style=\"font-size: 11pt; font-family: Verdana, sans-serif;\"></span></p>\r\n<p style=\"margin: 0cm 0cm 10.5pt; line-height: 14.25pt; background-color: white;\"><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\">Antes de fechar a compra, voc&ecirc; pode inserir o CEP do endere&ccedil;o de entrega na p&aacute;gina de detalhes do produto que quer comprar e o site calcula automaticamente o prazo estimado de entrega.</span></p>\r\n<p style=\"margin: 0cm 0cm 10.5pt; line-height: 14.25pt; background-color: white;\"><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\">Para obter uma estimativa do prazo de entrega:</span></p>\r\n<p class=\"MsoListParagraphCxSpFirst\" style=\"margin-bottom: 0.0001pt; text-indent: -18pt; line-height: 14.25pt; background-color: white;\"><!--[if !supportLists]--><span class=\"a-list-item\"><span style=\"font-size: 10.5pt; font-family: Symbol;\">&nbsp; &nbsp; &nbsp; &middot;<span style=\"font-stretch: normal; font-size: 7pt; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]--><span class=\"a-list-item\"><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\">Acesse a p&aacute;gina do produto que voc&ecirc; quer comprar.</span></span></p>\r\n<p class=\"MsoListParagraphCxSpLast\" style=\"margin-bottom: 0.0001pt; text-indent: -18pt; line-height: 14.25pt; background-color: white;\"><!--[if !supportLists]--><span style=\"font-size: 10.5pt; font-family: Symbol;\">&nbsp; &nbsp; &nbsp; &middot;<span style=\"font-stretch: normal; font-size: 7pt; line-height: normal; font-family: \'Times New Roman\';\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span><!--[endif]--><span class=\"a-list-item\"><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\">Insira o CEP para entrega e clique em</span></span><span class=\"apple-converted-space\"><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\">&nbsp;</span></span><strong><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\">CALCULAR FRETE.</span></strong><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\"></span></p>\r\n<p style=\"margin: 0cm 0cm 10.5pt; line-height: 14.25pt; background-color: white;\"><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\">&nbsp;</span></p>\r\n<p style=\"margin: 0cm 0cm 10.5pt; line-height: 14.25pt; background-color: white;\"><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\"></span><span style=\"font-family: Verdana, sans-serif; font-size: 10.5pt; line-height: 14.25pt;\">Voc&ecirc; ver&aacute; o prazo estimado de entrega do produto e o valor do frete, ou seja, uma estimativa de quanto tempo leva para o item ser entregue depois que ele &eacute; enviado. Normalmente, os itens s&atilde;o enviados em 7 dias &uacute;teis, ap&oacute;s o recebimento do pedido. &Eacute; poss&iacute;vel que demore mais dependendo da disponibilidade dos produtos, localidade ou do tempo necess&aacute;rio para processar o pagamento no seu cart&atilde;o de cr&eacute;dito.</span></p>\r\n<p style=\"margin: 0cm 0cm 10.5pt; line-height: 14.25pt; background-color: white;\"><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\">Depois de finalizado seu pedido, voc&ecirc; poder&aacute; consultar o rastreamento da entrega ou entrar em contato com a Maya Cosm&eacute;ticos nos meios de comunica&ccedil;&atilde;o (E-mail, Whatsapp, Skype e Telefone).</span></p>\r\n<p style=\"margin: 0cm 0cm 7.5pt; line-height: 13.5pt; background-color: white;\"><strong><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif; background-color: white;\">Nota:&nbsp;</span></strong><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif; background-color: white;\">A Maya Cosm&eacute;ticos faz entrega de produtos somente no territ&oacute;rio nacional (Brasil).</span><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif;\"></span></p>\r\n<p style=\"list-style: none; padding: 0px; margin-bottom: 10px; line-height: 18px; font-family: \'Lucida Sans Unicode\', \'Lucida Grande\', sans-serif; font-size: 12px;\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"background-color: white;\"><strong><span style=\"font-size: 10.5pt; font-family: Verdana, sans-serif; text-transform: uppercase;\">&nbsp;</span></strong></p>\r\n<p style=\"list-style: none; padding: 0px; margin-bottom: 10px; line-height: 18px; font-family: \'Lucida Sans Unicode\', \'Lucida Grande\', sans-serif; font-size: 12px;\"><strong><br /></strong></p>\r\n<p style=\"list-style: none; padding: 0px; margin-bottom: 10px; line-height: 18px; font-family: \'Lucida Sans Unicode\', \'Lucida Grande\', sans-serif; font-size: 12px;\">&nbsp;</p>\r\n<p style=\"list-style: none; padding: 0px; margin-bottom: 10px; line-height: 18px; font-family: \'Lucida Sans Unicode\', \'Lucida Grande\', sans-serif; font-size: 12px;\">&nbsp;</p>\r\n<p style=\"list-style: none; padding: 0px; margin-bottom: 10px; line-height: 18px; font-family: \'Lucida Sans Unicode\', \'Lucida Grande\', sans-serif; font-size: 12px;\">&nbsp;</p>', 'S', '2015-10-18 22:58:53', '2016-05-27 08:29:24', 1, NULL, NULL),
(3, 'Horário de Atendimento', NULL, 'horario-de-atendimento', '<p><span style=\"font-size: large;\">Segunda &agrave; sexta: 09h &agrave;s 18h</span></p>\r\n<p><span style=\"font-size: medium;\"><span style=\"font-size: large;\">S&aacute;bado: 9h &agrave;s 16h</span></span></p>\r\n<p><span style=\"font-size: medium;\"><span style=\"font-size: large;\"></span>V<span style=\"font-size: large;\">oc&ecirc; pode entrar em contato conosco por diversos canais:</span></span></p>\r\n<p><span style=\"font-size: large;\"><strong>whatsapp</strong>: (12) 98868-1452</span></p>\r\n<p><span style=\"font-size: large;\"><strong>e-mail:</strong> atendimento@mayacosmeticos.com.br</span></p>\r\n<p><span style=\"font-size: large;\"><strong>direct instagram</strong>:&nbsp;<a href=\"https://www.instagram.com/mayacosmeticos/\">https://www.instagram.com/mayacosmeticos/</a></span></p>\r\n<p><span style=\"font-size: large;\"><strong>messenger</strong>:&nbsp;<a href=\"https://www.messenger.com/t/mayacosmeticos\">https://www.messenger.com/t/mayacosmeticos</a></span></p>', 'S', '2016-01-02 12:17:17', '2023-10-25 19:48:30', 1, NULL, NULL),
(4, 'Programa de afiliados da Maya Cosméticos', NULL, 'programa-de-afiliados-da-maya-cosmeticos', '<h1 style=\"box-sizing: border-box; margin-bottom: 0px; font-size: 4rem; font-family: \'Opens Sans\', sans-serif; font-weight: 400; line-height: 1.1; color: #333333; text-align: start; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-weight: bold; font-size: small;\">Ganhe 8%&nbsp; por indicar a loja da Maya Cosm&eacute;ticos</span></h1>\r\n<p><span style=\"box-sizing: border-box; font-weight: bold; font-size: small;\"><br /></span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">GANHE DINHEIRO INDICANDO NOSSA LOJA VIRTUAL PARA SEUS AMIGOS, PARENTES, CLIENTES E SEGUIDORES SOCIAIS E GANHE DINHEIRO COM SUAS INDICA&Ccedil;&Otilde;ES;&nbsp;GRATIFICAMOS NOSSOS AFILIADOS COM 8<span style=\"box-sizing: border-box; font-weight: bold;\">%</span>&nbsp;SOBRE O VALOR DE TODAS AS COMPRAS REALIZADAS PELAS SUAS INDICA&Ccedil;&Otilde;ES.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"box-sizing: border-box; font-size: 14px;\">VOC&Ecirc; SER&Aacute; DEVER&Aacute; SE CADASTRAR EM NOSSA LOJA E ENTRA EM CONTATO CONOSCO, ASSIM SER&Aacute; CADASTRADOS COMO NOSSO&nbsp;<span style=\"box-sizing: border-box; font-weight: bold;\">CLIENTE AFILIADO.</span></span></p>\r\n<p><strong><br /></strong></p>\r\n<p><strong>QUEM PODE PARTICIPAR?</strong></p>\r\n<p><span style=\"color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 14px;\"><br /></span></p>\r\n<p><span style=\"color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 14px;\">Pessoas empreendedoras de qualquer classe social, que queiram trabalhar de forma honesta e lucrativa.</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">Exemplo:&nbsp;Blogueiras, Cabeleireira (o) s, revendedoras, consultoras, vendedores, Donas de casa, qualquer pessoa que&nbsp;</span><span style=\"box-sizing: border-box; font-size: 14px;\">esteja disposta a trabalhar!&nbsp;Pessoas envolvidas na &aacute;rea da beleza, moda, comercio, etc.</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">Pessoas que tenham:&nbsp;Site&nbsp;ou&nbsp;Blog,&nbsp;Redes sociais como face book, Youtube,&nbsp;Instagram,&nbsp;twitter.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"box-sizing: border-box; font-size: 14px;\">Voc&ecirc; dever&aacute; nos indicado qual local&nbsp;(URL)&nbsp;ser&aacute; feita as principais indica&ccedil;&otilde;es.</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">A parceria com a Ros&iacute; Cosm&eacute;ticos consiste na divulga&ccedil;&atilde;o da loja virtual Maya Cosmeticos&nbsp;&nbsp;nas redes sociais, Blogs, Sites,&nbsp;boca a boca, cart&otilde;es de visitas, banners etc...</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">Pagamos uma&nbsp;<span style=\"box-sizing: border-box; font-weight: bold;\">gratifica&ccedil;&atilde;o de 8%</span>&nbsp;sobre todas as compras realizadas pelas indica&ccedil;&otilde;es feitas pelos nossos&nbsp;afiliados, devidamente vindas do link c&oacute;digo que receber&aacute; para divulga&ccedil;&atilde;o.</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\">&nbsp;</p>\r\n<p><span style=\"box-sizing: border-box; font-size: 14px;\">O pagamento &eacute; v&aacute;lido p/compras concretizadas 100% (Conclu&iacute;das)</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">Nossos parceiros receber&atilde;o um link c&oacute;digo para fazer a divulga&ccedil;&atilde;o como exemplo:<span style=\"box-sizing: border-box; color: #0000ff;\">&nbsp;http://www.mayacosmeticos.com.br/?parceiro=2548</span></span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">&Eacute; muito f&aacute;cil divulgar basta copiar e colar em suas redes sociais, site ou Blog, enviar via e-mail, fazer a divulga&ccedil;&atilde;o boca a boca atrav&eacute;s de cart&otilde;es de visitas, banners, panfletos etc.</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">Nota:&nbsp;Nosso parceiro tem total&nbsp;liberdade para fazer a indica&ccedil;&atilde;o de seu link da melhor forma poss&iacute;vel.</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">ATEN&Ccedil;&Atilde;O: N&atilde;o se trata de representa&ccedil;&atilde;o comercial, vendedor, consultoria, &eacute; uma&nbsp;atividade sem v&iacute;nculo CLT.</span></p>\r\n<p>&nbsp;</p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><strong><span style=\"box-sizing: border-box; font-size: 14px;\">COMO FA&Ccedil;O&nbsp;PARA PARTICIPAR?</span></strong></p>\r\n<p><span style=\"font-size: 14px; color: #333333; font-family: \'Opens Sans\', sans-serif;\">Voc&ecirc; deve fazer seu&nbsp;cadastro completo em nossa loja como cliente e assinar nossa NEWSLETTER no rodap&eacute; da loja para receber nossas ofertas em seu e-mail.</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">Nos enviar um e-mail com seu nome, e n&oacute;s falar porque gostaria de participar&nbsp;do programa de afiliados;</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">Enviar a URL *endere&ccedil;o&nbsp;do&nbsp;seu site, blog, youtube&nbsp;ou redes sociais, Endere&ccedil;o do local&nbsp;principal&nbsp;que ir&aacute; divulgar.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"box-sizing: border-box; font-size: 14px;\">Importante deixar anotado para seus&nbsp;indicados (clientes) seu c&oacute;digo link para que todas as vezes que forem comprar usem o seu link, esta &eacute; a garantia que ser&aacute; gerado a gratifica&ccedil;&atilde;o para voc&ecirc;.</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\"><span style=\"box-sizing: border-box; font-weight: bold;\">Como pagamos as gratifica&ccedil;&otilde;es?</span></span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\"><span style=\"box-sizing: border-box; background-color: #ffff00;\">Atrav&eacute;s de deposito bancario indicado no ato da inscri&ccedil;&atilde;o ou&nbsp; caso voc&ecirc; queira </span><span style=\"box-sizing: border-box; background-color: #ffff00;\">resgatar em produtos na loja, a sua escolha e a qualquer momento, Simples: tem Saldo, pe&ccedil;a o seu cupom especial de resgate e use !</span></span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">A perman&ecirc;ncia no programa se dar&aacute; mediante a a&ccedil;&atilde;o efetiva do afiliado, na&nbsp;divulga&ccedil;&atilde;o da loja, com frequ&ecirc;ncia buscando as convers&otilde;es (indica&ccedil;&otilde;es) necess&aacute;rias.</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">Todo o acesso com o link &eacute; registrado em relat&oacute;rio e desta forma temos condi&ccedil;&otilde;es de verificar quem realmente tem trabalhado esta parceria e temos total controle de todo processo de compras, pessoas indicadas, quem comprou e quanto comprou.</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">Nossos parceiros tem uma &aacute;rea exclusiva de relat&oacute;rios de todas as movimenta&ccedil;&otilde;es&nbsp;de indica&ccedil;&otilde;es&nbsp;BackOffice&nbsp;quem comprou e quanto comprou etc...</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">Aten&ccedil;&atilde;o: Prazo para se manter ativo sem indica&ccedil;&otilde;es 90 dias, ap&oacute;s se n&atilde;o houver movimenta&ccedil;&atilde;o na conta nem o contato do Parceiro, a&iacute; poderemos&nbsp;remover o afiliado&nbsp;do programa sem aviso pr&eacute;vio.</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">(Situa&ccedil;&atilde;o que n&atilde;o gostar&iacute;amos, pois buscamos parceiros)</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\">&nbsp;</p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\">Qualquer d&uacute;vida fale com a gente, clicando aqui:</span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\"><br /></span></p>\r\n<p style=\"box-sizing: border-box; padding: 0px; position: relative; z-index: 0; margin-top: 1em; margin-bottom: 1em; width: auto; color: #333333; font-family: \'Opens Sans\', sans-serif; font-size: 10px; background-color: #ffffff;\"><span style=\"box-sizing: border-box; font-size: 14px;\"><span style=\"box-sizing: border-box; font-weight: bold;\"><br /></span></span></p>', 'N', '2018-04-22 12:07:22', '2019-03-20 07:16:55', 1, NULL, NULL),
(10, 'Compre com segurança', NULL, 'compra-segura', '<p><span style=\"font-size: large;\">Nosso site &eacute; <strong>100% seguro</strong> pois possuimos <strong>certificado SS</strong>L, o que garante a <strong>criptografia e seguran&ccedil;a</strong> contra roubo dos seus dados no nosso site. Para assegurar que o site &eacute; realmente seguro, ele deve possuir um cadeado do lado esquerdo do endere&ccedil;o do site.</span></p>\r\n<p><span style=\"font-size: large;\">Al&eacute;m disso, contamos com diversos <strong style=\"font-size: medium;\">canais de atendiment</strong>o para que voc&ecirc; possa tirar d&uacute;vidas e acompanhar seu pedido de forma mais transparente poss&iacute;vel.</span></p>\r\n<p><span style=\"font-size: large;\">Todo o processo de <strong style=\"font-size: medium;\">compra</strong> de <strong style=\"font-size: medium;\">Cart&atilde;o de Cr&eacute;dito</strong> e <strong style=\"font-size: medium;\">Boleto</strong>&nbsp;&eacute; feito pelo <strong style=\"font-size: medium;\">PagSeguro</strong>, e <strong style=\"font-size: medium;\">Pix</strong> pela <strong style=\"font-size: medium;\">Gerencianet</strong> o que assegura que seu pagamento est&aacute; seguro por empresas que est&atilde;o a anos no mercado de gateway de pagamentos.</span></p>\r\n<p><span style=\"font-size: large;\">&nbsp;A <strong style=\"font-size: medium;\">entrega</strong> dos pedidos &eacute; feita pelos <strong style=\"font-size: medium;\">Correios</strong> ou <strong style=\"font-size: medium;\">Transportadora</strong>, disponibilizamos um c&oacute;digo de rastreio logo ap&oacute;s o envio do pedido, para que voc&ecirc; acompanhe todo o caminho do seu pedido. Garantimos 100% das nossas entregas ou devolvemos seu dinheiro!</span></p>', 'S', '2019-06-16 16:04:20', '2022-12-20 06:56:30', 1, NULL, NULL),
(11, 'Formas de Pagamento', NULL, 'formas-de-pagamento', '<p><span style=\"font-size: large;\">Nossos pagamentos s&atilde;o gerenciados pelo <strong>PagSeguro e Gerencianet</strong>, empresas lideres no mercado brasileiro em recebimentos de pagamento, o que garante que seu dinheiro est&aacute; seguro com empresas s&eacute;rias que est&atilde;o &agrave; anos no mercado.&nbsp;<span style=\"background-color: #ffffff;\">O <strong>PagSeguro</strong> faz a intermedia&ccedil;&atilde;o do pagamento de <strong>Boleto e Cart&atilde;o de Cr&eacute;dito</strong> e a <strong>Gerencianet</strong> a intermedi&ccedil;a&otilde; de <strong>Pix</strong>, o que quer dizer que essas empresas recebem seu pagamento e depois repassa o valor para nossa loja.</span></span></p>\r\n<p><span style=\"font-size: large;\">Nossa loja disponibilza 3 meios de pagamento:</span></p>\r\n<p><span style=\"background-color: #ffffff; font-size: large;\">* &Agrave;&nbsp; vista no Boleto.&nbsp; <strong>(Temporariamente indispon&iacute;vel)</strong></span><br /><span style=\"font-size: large;\"><span style=\"background-color: #ffffff;\">* No cart&atilde;o de cr&eacute;dito at&eacute; 3 vezes sem juros&nbsp;<strong>(Temporariamente indispon&iacute;vel)</strong><br /></span><span style=\"background-color: #ffffff;\">* &Agrave; vista no Pix</span></span>&nbsp;</p>', 'S', '2019-06-16 16:31:45', '2024-06-23 19:51:41', 1, NULL, NULL),
(12, 'Política de Privacidade', NULL, 'politica-de-privacidade', '<p><span style=\"font-size: large;\">Nosso site &eacute; protegido contra roubo de dados atrav&eacute;s de <strong>certificado SS</strong>L. <strong>N&atilde;o armazenamos dados</strong> de pagamento como dados de cart&atilde;o de cr&eacute;dito&nbsp; e tamb&eacute;m <strong>n&atilde;o forcecemos seus dados pessoais a terceiros</strong>.</span></p>', 'S', '2019-06-16 16:34:28', '2022-12-20 07:01:26', 1, NULL, NULL),
(13, 'Frete Grátis Aniversário de São José dos Campos', NULL, 'aniversario-sjc-252-anos', '<p style=\"font-size: 12px;\"><span style=\"font-size: large; background-color: #ffffff;\">No anivers&aacute;rio de S&atilde;o Jos&eacute; dos Campos&nbsp; de 252 anos, quem ganha s&atilde;o os joseenses! Frete gr&aacute;tis na modalidade entrega normal em compras de produtos de qualquer valor, basta adicionar na&nbsp;<a href=\"../../minha-sacola\" title=\"Minha Sacolsa\">sacola</a>&nbsp;e calcular o frete&nbsp; para obter o desconto. Essa promo&ccedil;&atilde;o &eacute; v&aacute;lida somente&nbsp; entre&nbsp; 27/07/2019 a 29/07/2019. D&uacute;vidas, acesse nossos canais de atendimento.</span></p>\r\n<p style=\"font-size: 12px;\">&nbsp;</p>\r\n<p style=\"font-size: 12px;\"><a href=\"../../../faq\" title=\"Perguntas Frequentes\"><span style=\"font-size: large;\">Saiba Mais sobre nossas politicas de venda e troca</span></a></p>', 'N', '2019-07-26 08:02:58', '2019-07-26 08:02:58', 1, NULL, NULL),
(14, 'Frete Grátis para compras acima de 200,00', NULL, 'frete-gratis-2020', '<p><span style=\"font-size: large;\">Nas compras acima de 200,00 voc&ecirc; pode ter frete gr&aacute;tis para a modalidade de&nbsp;<strong>Correios PAC</strong>, basta adicionar os produtos na sacola, calcular o frete e escolher a modalidade de frete normal para ter frete gr&aacute;tis.</span></p>\r\n<p><span style=\"font-size: large;\">Esta promo&ccedil;&atilde;o &eacute; v&aacute;lida por tempo limitado.</span></p>\r\n<p><span style=\"font-size: large;\"><br /></span></p>\r\n<p><span style=\"font-size: large;\"><a href=\"../../\">Quero ver os produtos</a></span></p>', 'S', '2019-07-30 07:03:55', '2022-12-20 07:03:07', 1, NULL, NULL),
(22, 'Frete Grátis para Jacareí', NULL, 'frete-gratis-jacarei', '<p><span style=\"font-size: large;\">Agora temos mais uma comodidade para os moradores da nossa querida Jacare&iacute;: frete gr&aacute;tis para compras de qualquer valor.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Mas corre que &eacute; s&oacute; at&eacute; o final de 219, virou 2020, j&aacute; era!</span></p>', 'N', '2019-12-04 20:45:20', '2020-03-21 11:35:25', 1, NULL, NULL),
(27, 'Compre na Loja Física', NULL, 'compre-na-loja-fisica', '<div itemscope itemtype=\"https://schema.org/HealthAndBeautyBusiness\" style=\"font-size:large\">\r\n    <div>\r\n        <i class=\"fa-solid fa-location-dot\"></i>\r\n        &nbsp;<span itemprop=\"name\">Maya Cosméticos<span>\r\n        <div itemprop=\"address\" itemscope itemtype=\"https://schema.org/PostalAddress\">\r\n            <span itemprop=\"streetAddress\">Avenida Vale do Paraíba, 485 <br> Parque Santo Antonio</span><br>\r\n            <span itemprop=\"addressLocality\"> Jacareí</span> -\r\n            <span itemprop=\"addressRegion\">SP</span><br>\r\n            <span itemprop=\"postalCode\">12309-000</span>\r\n        </div>\r\n        <iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3664.1407893442943!2d-45.958608885574094!3d-23.31065008480794!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x94cdcb0bd52ad7a9%3A0x48f9b45f3b3e8f23!2sMaya%20Cosm%C3%A9ticos!5e0!3m2!1spt-BR!2sbr!4v1672262015299!5m2!1spt-BR!2sbr\" width=\"100%\" height=\"450\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>\r\n    </div>\r\n</div>', 'S', '2022-12-28 18:35:43', '2022-12-28 18:35:43', 1, NULL, NULL);
INSERT INTO `pagseguro_transactions` (`id`, `contact_id`, `order_id`, `transacao_id`, `referencia`, `tipo_frete`, `valor_frete`, `extras`, `anotacao`, `data_transacao`, `metodo_pagamento`, `status_transacao`, `num_itens`, `parcelas`, `created`, `modified`) VALUES
