(2100, 'HB319', 'UN', '0', 87, 85, 169, 'Sérum facial Argila Rosa', 'Compre Sérum facial Argila Rosa com 7% de desconto à vista no Boleto', '<p><strong><em><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">S&eacute;rum Facial</span></span></em></strong></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\"><br /></span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">Cont&eacute;m provitamina B5</span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\"><br /></span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">S&eacute;rum Facial Ruby Rose Argila Rosa, possui textura leve e n&atilde;o oleosa, desenvolvido para todos os tipos de pele.</span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\"><br /></span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">Elaborado com Argila Rosa, rica em sais minerais, Provitamina B5, Col&aacute;geno e Elastina, promove a&ccedil;&atilde;o revitalizante, hidratante e nutritiva, auxilia na reposi&ccedil;&atilde;o de col&aacute;geno deixando sua pele hidratada e com toque sedoso. Livre de parabenos.</span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\"><br /></span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">Modo de Uso: Aplicar o s&eacute;rum no rosto sobre a pele limpa e seca massageando at&eacute; a completa absor&ccedil;&atilde;o.</span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\"><br /></span></span></p>\r\n<p><strong><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">Frequ&ecirc;ncia</span></span></strong></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">Usar 2x na semana</span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\"><br /></span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">Indicado para todos os tipos de pele</span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\"><br /></span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">Composi&ccedil;&atilde;o: Aqua, Cyclopentasiloxane, Dimethiconol, Butylene Glycol, Caprylic/Capric Triglyceride, Dimethicone, Montmorillonite, Sodium Polyacrylate, Parfum, Caprylyl Glycol, Phenoxyethanol, Cyclomethicone, Dimethicone Crosspolymer, PEG/PPG-18/18 Dimethicone, Trideceth-6, Panthenol, Disodium EDTA, DMDM Hydantoin, Hydrolyzed Collagen, Hydrolyzed Elastin, Octadecyl Di-T-Butyl-4-Hydroxyhydrocinnamate, Benzotriazolyl Dodecyl P-Cresol, Iodopropynyl Butylcarbamate, Butylphenyl Methylpropional, Coumarin, D-Limonene, Geraniol, Hexyl Cynnamal, Linalool.</span></span></p>', 13.28, 23.90, 3.00, 20.00, 0.00, '', '', 0, 'N', NULL, 'N', 0, NULL, 'N', '', 'serum-facial-argila-rosa', 'Sérum facial Argila Rosa', '2020-09-22 08:19:57', '2022-03-15 18:59:19', NULL, NULL, NULL),
(2101, 'HB404', 'UN', '0', 87, 85, 169, 'Máscara Facial Argila Rosa', 'Compre Máscara Facial Argila Rosa da Ruby Rose com 7% de desconto à vista no Boleto', '<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">M&aacute;scara Facial</span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\"><br /></span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">A&ccedil;&atilde;o revitalizante, esfolia&ccedil;&atilde;o suave, aux&iacute;lio no controle, da oleosidade. cont&eacute;m provitamina B5.</span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\"><br /></span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">Possui a&ccedil;&atilde;o revitalizante e auxilia no controle da oleosidade excessiva. Com esfolia&ccedil;&atilde;o suave ela age limpando gentilmente e deixando a pele aveludada e sedosa.</span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\"><br /></span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">Argila Rosa: A jun&ccedil;&atilde;o das argilas branca e vermelha, sua principal caracter&iacute;stica &eacute; ser extremamente suave e menos absorvente do que as outras argilas, pois &eacute; rica em sais minerais, al&eacute;m de possuir a&ccedil;&atilde;o suavizante e revitalizante.</span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\"><br /></span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">Modo de Uso: Com a pele limpa aplique a m&aacute;scara no rosto evitando a regi&atilde;o dos olhos e l&aacute;bios. Deixe agir por cerca de 20 minutos, retire com &aacute;gua morna. Seque o rosto delicadamente e finalize aplicando o s&eacute;rum argila rosa.</span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\"><br /></span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">Frequ&ecirc;ncia Usar 2x na semana e ap&oacute;s usar o S&eacute;rum</span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\"><br /></span></span></p>\r\n<p><span style=\"color: #000000; font-size: large;\"><span style=\"color: #4d4d4d; font-family: Montserrat, sans-serif;\">Composi&ccedil;&atilde;o: Aqua, Montmorillonite, Alcohol, Ceteareth-20, Butylene Glycol, Hydroxypropyl Starch Phosphate, Stearyl Alcohol, Cetyl Alcohol, Parfum, Octadecyl Di-T-Butyl-4-Hydroxyhydrocinnamate, Panthenol, DMDM Hydantoin, Benzotriazolyl Dodecyl P-Cresol, Arachidyl Alcohol, Myristyl Alcohol, Lauryl Alcohol, Iodopropynyl Butylcarbamate, Butylphenyl Methylpropional, Coumarin, Hexyl Cynnamal.</span></span></p>', 9.50, 16.99, 3.00, 20.00, 0.00, '', '', 0, 'N', NULL, 'N', 0, NULL, 'N', '', 'mascara-facial-argila-rosa', 'Máscara Facial Argila Rosa', '2020-09-22 08:25:25', '2023-09-08 17:05:16', NULL, NULL, NULL),
