(2448, '160', 'UN', '0', 85, 217, 169, 'Sérum Facial Peeling 30ml Max love', 'Compre Sérum Facial Peeling da Max Love com 7% de desconto à vista no Boleto na loja virtual', '<p><span style=\"font-size: large;\">&nbsp;O S&eacute;rum Facial Peeling Max Love estimula a esfolia&ccedil;&atilde;o da pele e auxilia na uniformiza&ccedil;&atilde;o melhorando a cor e a textura, al&eacute;m de auxiliar na redu&ccedil;&atilde;o dos poros.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">A&ccedil;&atilde;o</span></p>\r\n<p><span style=\"font-size: large;\">Cont&eacute;m Alfa-hidroxi&aacute;cidos, que deixam a pele mais fina, lisa e iluminada, pois estimulam a renova&ccedil;&atilde;o celular e Beta-hidroxi&aacute;cido, um &aacute;cido que penetra no poro regulando a produ&ccedil;&atilde;o seb&aacute;cea, sendo assim ideal para as peles oleosas e com acne.&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Conselho de Aplica&ccedil;&atilde;o</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Aplicar &agrave; noite sobre a pele limpa, massageando at&eacute; a completa absor&ccedil;&atilde;o. Ao acordar, lave o rosto com sabonete facial de sua prefer&ecirc;ncia. Na primeira semana, Evitar exposi&ccedil;&atilde;o solar durante o uso do produto. Durante a primeira semana de uso, aplicar pequenas quantidades de produto, em dias alternados.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Resultado</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Pele mais uniforme, lisa e iluminada.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">&nbsp;Validade: 12/23.</span></p>', NULL, 14.90, NULL, NULL, 12.00, '', '', 0, 'S', 0.200, 'N', 0, NULL, 'S', 'serum-facial-peeling', 'serum-facial-peeling', 'Sérum Facial Peeling', '2021-04-10 17:50:03', '2023-12-29 08:15:19', 18, 14, 6),
(2449, '60001', 'UN', '0', 85, 217, 169, 'Sabonete Facial Primer Pré-Maquiagem', 'Compre Sabonete Facial Primer Pré-Maquiagem da Max Love com 7% de desconto no Boleto na loja online', '<p><strong><em><span style=\"font-size: large;\">Sabonete Primer Pr&eacute;-Maquiagem 90ml &ndash; Max Love</span></em></strong></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">O Sabonete Primer Pr&eacute; Make da Max Love foi desenvolvido para Desenvolvido para condicionar a pele para receber a maquiagem. Dermatologicamente testado.</span></p>\r\n<p><span style=\"font-size: large;\">Possui &Aacute;cido Hialur&ocirc;nico e Bioativos &agrave; base de Extrato de ch&aacute; verde . A pele fica muito macia, lisinha pronta pra receber sua Make.</span></p>', NULL, 10.80, NULL, NULL, 0.00, '', '', 0, 'N', 0.200, 'N', 0, NULL, 'N', 'sabonete-facial-primer-pre-maquiagem', 'sabonete-facial-primer-pre-maquiagem', 'Sabonete Facial Primer Pré-Maquiagem', '2021-04-10 19:22:22', '2023-03-06 10:53:09', 18, 14, 6),
