(2677, 'CL5-9', 'UN', '0', 78, 209, 185, 'Cílios Cl5-9 Fios Volumosos, Longos E Médios Nos Cantos', '', '<p><span style=\"color: #000000; font-size: large;\">C&iacute;lios posti&ccedil;os da Macrilan CL5-9 especialmente desenvolvidos para preencher, real&ccedil;ar e dar volume aos c&iacute;lios naturais com praticidade.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Aqui na Voudemake voc&ecirc; encontra toda a linha de Pinc&eacute;is e Acess&oacute;rios da marca Macrilan.</span></p>', NULL, 16.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.080, 'N', 0, NULL, 'N', 'cilios-cl5-9-fios-volumosos-longos-e-medios-nos-cantos', 'cilios-cl5-9-fios-volumosos-longos-e-medios-nos-cantos', 'Cílios Cl5-9 Fios Volumosos, Longos E Médios Nos Cantos', '2022-07-19 15:29:36', '2022-11-12 15:26:27', 16, 14, 6),
(2678, 'CL8-7', 'UN', '0', 78, 209, 185, 'Cílios Postiço Macrilan Volume Médio CL8-7', '', '<p><span style=\"color: #000000; font-size: large;\">C&iacute;lios posti&ccedil;os da Macrilan CL8-7 especialmente desenvolvidos para preencher, real&ccedil;ar e dar volume aos c&iacute;lios naturais com praticidade. Suas cerdas s&atilde;o extremamente macias, o que proporciona maior naturalidade e conforto, a base transparente al&eacute;m de n&atilde;o incomodar ainda d&aacute; acabamento ao encaixe dos c&iacute;lios. Garanta c&iacute;lios poderosos e conforto com a Macrilan,</span></p>', NULL, 12.90, NULL, NULL, 0.00, '', '', 0, 'N', 0.080, 'N', 0, NULL, 'N', 'cilios-postico-macrilan-volume-medio-cl8-7', 'cilios-postico-macrilan-volume-medio-cl8-7', 'Cílios Postiço Macrilan Volume Médio CL8-7', '2022-07-19 15:34:01', '2023-07-21 12:22:33', 16, 14, 6),
(2679, 'PI-2', 'UN', '0', 78, 209, 158, ' Pinca Para Sobrancelha Ponta Reta Profissional PI-2 Macrilan', '', '<p><span style=\"color: #000000; font-size: large;\">Pin&ccedil;a Macrilan PI-2</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Pin&ccedil;a Macrilan PI-2 especialmente desenvolvida para remo&ccedil;&atilde;o de pelos da face e corpo.Com acabamento dourado e corte reto para uso pessoal e profissional com praticidade e seguran&ccedil;a.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Especifica&ccedil;&atilde;o T&eacute;cnica</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Peso l&iacute;quido: 14,5 g</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Altura: 16 cm</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Circunfer&ecirc;ncia: 14 cm</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Modo de usar:</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Agite antes de usar.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Utilize para remo&ccedil;&atilde;o de pelos da face e corpo.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Composi&ccedil;&atilde;o: A&ccedil;o carbono e pintura dourada.</span></p>', NULL, 15.90, NULL, NULL, 3.00, '', '', 0, 'S', 0.100, 'N', 0, NULL, 'N', 'pinca-para-sobrancelha-ponta-reta-profissional-pi-2-macrilan', 'pinca-para-sobrancelha-ponta-reta-profissional-pi-2-macrilan', ' Pinca Para Sobrancelha Ponta Reta Profissional PI-2 Macrilan', '2022-07-19 15:49:12', '2022-09-23 11:38:58', 16, 14, 6),
(2680, '6124B', 'UN', '0', 112, 209, 185, 'Pinça de Alta Precisão com Ponta Chanfrada Marco Boni', '', '', NULL, 14.99, NULL, NULL, 0.00, '', '', 0, 'N', 0.080, 'N', 0, NULL, 'N', 'pinca-de-alta-precisao-com-ponta-chanfrada-marco-boni', 'pinca-de-alta-precisao-com-ponta-chanfrada-marco-boni', 'Pinça de Alta Precisão com Ponta Chanfrada Marco Boni', '2022-07-19 16:04:46', '2022-09-28 09:53:17', 16, 14, 6),
(2681, '100294', 'UN', '0', 113, 209, 158, 'Pincel Dupla Função Chanfrado e ponta Palito', '', '<p><span style=\"color: #000000; font-size: large;\">O Pincel Dupla Fun&ccedil;&atilde;o Chanfrado e Ponta Palito Arte Sedu&ccedil;&atilde;o, &eacute; perfeito para aplica&ccedil;&atilde;o de Henna em sobrancelhas.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Ponta Chanfrado perfeito para aplica&ccedil;&atilde;o de Henna</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Ponta Palito ideal para aux&iacute;lio na limpesa.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Este pincel faz parte da linha Profissional de pinc&eacute;is Arte Sedu&ccedil;&atilde;o.</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Ideal para quem &eacute; profissional Designer de sobrancelha e tamb&eacute;m para quem est&aacute; come&ccedil;ando.&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Resultado perfeito.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Feito com cerdas de pelo sint&eacute;tico sendo assim mais flex&iacute;vel</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Virola c&ocirc;ncava met&aacute;lica, dando mais durabilidade ao seu pincel</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Cabo na cor preta de material reciclado&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Qualidade incompar&aacute;vel</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000; font-size: large;\">Limpeza e conserva&ccedil;&atilde;o:</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Tintas a base de &aacute;gua, lavar com &aacute;gua morna e sab&atilde;o neutro.</span></p>\r\n<p><span style=\"color: #000000; font-size: large;\">Tintas a base de solventes, limpar com thinner, enxugar e lavar com &aacu