(2778, 'HT7485', 'UN', '0', 77, 155, 119, 'Corretivo Facial Líquido Cor:05 Alta Cobertura Matte Ultra Chic ', '', '<p><span style=\"font-size: large;\">Corretivo L&iacute;quido Ultra Chic Jasmyne</span></p>\r\n<p><span style=\"font-size: large;\">O Corretivo L&iacute;quido Ultra Chic possu&iacute; uma cobertura mais leve e suave, perfeita para voc&ecirc; que quer uma make mais basiquinha, sem aquela alt&iacute;ssima cobertura.</span></p>\r\n<p><span style=\"font-size: large;\">S&atilde;o 4 tonalidades de corretivos para voc&ecirc; fazer uma make linda</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Especifica&ccedil;&atilde;o T&eacute;cnica</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Peso l&iacute;quido unit&aacute;rio: 4 ml</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Altura: 11 cm</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Circunfer&ecirc;ncia: 6,5 cm</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Composi&ccedil;&atilde;o:</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Aqua, Glycerin, Cyclotetrasiloxane, Cetyl Peg/PPG-10/ 1 Dimethicone, Cera Microcristallina, Cera Alba, Caprylhydroxamic Acid (And) Caprylyl Glycol (And) Glycerin, Phenoxyethanol, Tocopheryl Acetata.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Poder&aacute; conter: CI 77891, CI 77401, CI 77492, CI 77499.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Modo de usar:</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Aplique o corretivo com o aplicador e d&ecirc; leves batidinhas com um pincel, esponja ou ponta dos dedos na &aacute;rea que deseja uniformizar ou disfar&ccedil;ar imperfei&ccedil;&otilde;es.</span></p>', NULL, 14.00, NULL, NULL, 3.00, '', '', 0, 'S', 0.200, 'N', 0, NULL, 'N', 'corretivo-facial-liquido-alta-cobertura-matte-ultra-chic-cor-05', 'corretivo-facial-liquido-alta-cobertura-matte-ultra-chic-cor-05', 'Corretivo Facial Líquido Cor:05 Alta Cobertura Matte Ultra Chic ', '2022-12-22 16:22:56', '2023-05-18 09:34:29', 16, 11, 6),
(2779, 'HT7484', 'UN', '0', 77, 155, 119, 'Corretivo Facial Líquido Cor:06 Alta Cobertura Matte Ultra Chic ', '', '<p><span style=\"font-size: large;\">Corretivo L&iacute;quido Ultra Chic Jasmyne</span></p>\r\n<p><span style=\"font-size: large;\">O Corretivo L&iacute;quido Ultra Chic possu&iacute; uma cobertura mais leve e suave, perfeita para voc&ecirc; que quer uma make mais basiquinha, sem aquela alt&iacute;ssima cobertura.</span></p>\r\n<p><span style=\"font-size: large;\">S&atilde;o 4 tonalidades de corretivos para voc&ecirc; fazer uma make linda</span></p>\r\n<p><span style=\"font-size: large;\"><br /></span></p>\r\n<p><span style=\"font-size: large;\">Especifica&ccedil;&atilde;o T&eacute;cnica</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Peso l&iacute;quido unit&aacute;rio: 4 ml</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Altura: 11 cm</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Circunfer&ecirc;ncia: 6,5 cm</span></p>\r\n<p><span style=\"font-size: large;\">Composi&ccedil;&atilde;o:</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Aqua, Glycerin, Cyclotetrasiloxane, Cetyl Peg/PPG-10/ 1 Dimethicone, Cera Microcristallina, Cera Alba, Caprylhydroxamic Acid (And) Caprylyl Glycol (And) Glycerin, Phenoxyethanol, Tocopheryl Acetata.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Poder&aacute; conter: CI 77891, CI 77401, CI 77492, CI 77499.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Modo de usar:</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Aplique o corretivo com o aplicador e d&ecirc; leves batidinhas com um pincel, esponja ou ponta dos dedos na &aacute;rea que deseja uniformizar ou disfar&ccedil;ar imperfei&ccedil;&otilde;es.</span></p>', NULL, 14.00, NULL, NULL, 4.00, '', '', 0, 'S', 0.200, 'N', 0, NULL, 'N', 'corretivo-facial-liquido-cor-06-alta-cobertura-matte-ultra-chic', 'corretivo-facial-liquido-cor-06-alta-cobertura-matte-ultra-chic', 'Corretivo Facial Líquido Cor:06 Alta Cobertura Matte Ultra Chic ', '2022-12-22 16:28:16', '2023-05-18 10:38:48', 16, 11, 6),
