(2908, 'BS0302', 'UN', '0', 135, 2, 180, 'Blush Faces cor 02', 'Blush em pó compacto cor Pêssego 02 Fenzza', '<p><span style=\"font-size: large;\">Blush Faces Fenzza</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Um bom Blush &eacute; pe&ccedil;a fundamental na maquiagem mesmo que seja a mais b&aacute;sica e do dia a dia.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">O Blush Face Fenzza &eacute; super fininho e vai dar aquele ar de sa&uacute;de que a gente tanto ama!</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Dispon&iacute;vel em 4 cores, o Blush Face Fenzza vai se tornar seu queridinho e indispens&aacute;vel.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\">Cont&eacute;m: 10g</span></p>', 5.30, 10.00, NULL, NULL, 4.00, '', '', 0, 'S', 0.200, 'N', 0, NULL, 'S', 'blush-faces-cor-02', 'blush-faces-cor-02', 'Blush Faces cor 02 - Fenzza', '2023-08-04 12:21:19', '2023-09-01 10:26:14', 18, 14, 6),
(2909, 'SP272IL', 'UN', '0', 88, 2, 144, 'Iluminador The Best iluminador', 'Iluminador com 4 opções de cores Sp Colors', '<p><span style=\"font-size: large;\">O Iluminador &eacute; indispens&aacute;vel na maquiagem para quem gosta de uma pele iluminada. Ele d&aacute; aquele vi&ccedil;o a pele, o toque final indispens&aacute;vel a maquiagem, seja ela mais elaborada ou mesmo a b&aacute;sica. E o The Best TRIO SP Colors - Iluminador &eacute; aquele produtinho que n&atilde;o pode faltar na sua bolsa!</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"font-size: large;\"><strong>MODO DE USAR</strong></span></p>\r\n<p><span style=\"font-size: large;\">Com auxlios de um pincel, aplique o iluminador diretamente sobre o rosto para iluminar as &aacute;reas desejadas.</span></p>\r\n<p>&nbsp;</p>', 8.10, 13.90, NULL, NULL, 7.00, '', '', 0, 'S', 0.100, 'N', 0, NULL, 'S', 'iluminador-the-best-iluminador', 'iluminador-the-best-iluminador', 'Iluminador  The Best Trio The Best iluminador - Sp Colors', '2023-08-04 12:31:03', '2023-09-22 07:31:19', 17, 14, 6),
